/* 縦横の判定は1か所だけ。閾値: 縦横比 1.05 以上=横長 / 0.95 以下=縦長 / その間=正方形に近い。
   閾値を変えるときはここだけ変える (画面ごとに別の判定を作らない)。 */
export const ORIENTATION_LANDSCAPE = 1.05;
export const ORIENTATION_PORTRAIT = 0.95;
export function orientationOf(id) {
  const d = PHOTO_DIMS[id];
  if (!d || !d[1]) return null;            // 不明は null。「横」と決めつけない
  const r = d[0] / d[1];
  if (r >= ORIENTATION_LANDSCAPE) return "landscape";
  if (r <= ORIENTATION_PORTRAIT) return "portrait";
  return "square";
}
export const aspectOf = (id) => (PHOTO_DIMS[id] ? PHOTO_DIMS[id][0] / PHOTO_DIMS[id][1] : null);
